public with sharing class ContactDomainService {

    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> result = new Map<String, List<Contact>>();
        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        List<Contact> contacts = [
            SELECT Id, Email, AccountId
            FROM Contact
            WHERE AccountId IN :accountIds
            AND Email != null
            WITH USER_MODE
        ];

        for (Contact c : contacts) {
            String email = c.Email == null ? null : c.Email.trim();
            if (String.isBlank(email)) {
                continue;
            }
            Integer atIndex = email.lastIndexOf('@');
            if (atIndex < 0 || atIndex == email.length() - 1) {
                continue;
            }
            String domain = email.substring(atIndex + 1).trim().toLowerCase();
            if (String.isBlank(domain)) {
                continue;
            }
            List<Contact> bucket = result.get(domain);
            if (bucket == null) {
                bucket = new List<Contact>();
                result.put(domain, bucket);
            }
            bucket.add(c);
        }
        return result;
    }
}
