```apex
public with sharing class RecordSearchService {

    public class SearchException extends Exception {}

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        if (String.isBlank(objectApiName)) {
            throw new SearchException('Object name is required.');
        }
        Schema.SObjectType sot = Schema.getGlobalDescribe().get(objectApiName.trim().toLowerCase());
        if (sot == null) {
            throw new SearchException('Unknown object: ' + objectApiName);
        }
        Schema.DescribeSObjectResult objDesc = sot.getDescribe();
        if (!objDesc.isAccessible()) {
            throw new SearchException('You do not have access to object ' + objDesc.getName());
        }
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('At least one field is required.');
        }
        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be between 1 and 200.');
        }

        Map<String, Schema.SObjectField> fieldMap = objDesc.fields.getMap();

        List<String> selectFields = new List<String>{ 'Id' };
        Set<String> seen = new Set<String>{ 'id' };
        for (String f : fields) {
            Schema.DescribeFieldResult d = resolve(fieldMap, f, objDesc);
            if (!d.isAccessible()) {
                throw new SearchException('No access to field ' + d.getName());
            }
            if (seen.add(d.getName().toLowerCase())) {
                selectFields.add(d.getName());
            }
        }

        Map<String, Object> binds = new Map<String, Object>();
        List<String> conditions = new List<String>();
        if (filters != null) {
            Integer i = 0;
            for (String key : filters.keySet()) {
                Schema.DescribeFieldResult d = resolve(fieldMap, key, objDesc);
                if (!d.isAccessible()) {
                    throw new SearchException('No access to field ' + d.getName());
                }
                if (!d.isFilterable()) {
                    throw new SearchException('Field cannot be filtered: ' + d.getName());
                }
                String bindName = 'b' + i;
                binds.put(bindName, coerce(filters.get(key), d));
                conditions.add(d.getName() + ' = :' + bindName);
                i++;
            }
        }

        String orderBy = '';
        if (!String.isBlank(orderByField)) {
            Schema.DescribeFieldResult d = resolve(fieldMap, orderByField, objDesc);
            if (!d.isAccessible()) {
                throw new SearchException('No access to field ' + d.getName());
            }
            if (!d.isSortable()) {
                throw new SearchException('Field cannot be sorted: ' + d.getName());
            }
            orderBy = ' ORDER BY ' + d.getName() + ' ASC';
        }

        binds.put('maxRowsLimit', maxRows);
        String soql = 'SELECT ' + String.join(selectFields, ', ') + ' FROM ' + objDesc.getName();
        if (!conditions.isEmpty()) {
            soql += ' WHERE ' + String.join(conditions, ' AND ');
        }
        soql += orderBy + ' LIMIT :maxRowsLimit';

        try {
            return Database.queryWithBinds(soql, binds, AccessLevel.USER_MODE);
        } catch (Exception e) {
            throw new SearchException('Search failed: ' + e.getMessage());
        }
    }

    private static Schema.DescribeFieldResult resolve(
        Map<String, Schema.SObjectField> fieldMap,
        String name,
        Schema.DescribeSObjectResult objDesc
    ) {
        if (String.isBlank(name)) {
            throw new SearchException('Field name must not be blank.');
        }
        Schema.SObjectField f = fieldMap.get(name.trim().toLowerCase());
        if (f == null) {
            throw new SearchException('Unknown field ' + name + ' on ' + objDesc.getName());
        }
        return f.getDescribe();
    }

    private static Object coerce(Object value, Schema.DescribeFieldResult d) {
        if (value == null) {
            return null;
        }
        Schema.DisplayType t = d.getType();
        try {
            if (t == Schema.DisplayType.BOOLEAN) {
                if (value instanceof Boolean) {
                    return value;
                }
                String s = String.valueOf(value).trim().toLowerCase();
                if (s == 'true') {
                    return true;
                }
                if (s == 'false') {
                    return false;
                }
                throw new SearchException('Invalid Boolean value for ' + d.getName());
            }
            if (t == Schema.DisplayType.DATE) {
                if (value instanceof Date) {
                    return value;
                }
                if (value instanceof Datetime) {
                    return ((Datetime) value).date();
                }
                return Date.valueOf(String.valueOf(value).trim());
            }
            if (t == Schema.DisplayType.DATETIME) {
                if (value instanceof Datetime) {
                    return value;
                }
                if (value instanceof Date) {
                    Date dt = (Date) value;
                    return Datetime.newInstance(dt.year(), dt.month(), dt.day());
                }
                return (Datetime) JSON.deserialize(
                    '"' + String.escapeSingleQuotes(String.valueOf(value).trim()) + '"',
                    Datetime.class
                );
            }
            if (t == Schema.DisplayType.INTEGER) {
                if (value instanceof Integer) {
                    return value;
                }
                return Integer.valueOf(String.valueOf(value).trim());
            }
            if (t == Schema.DisplayType.LONG) {
                if (value instanceof Long || value instanceof Integer) {
                    return Long.valueOf(String.valueOf(value));
                }
                return Long.valueOf(String.valueOf(value).trim());
            }
            if (t == Schema.DisplayType.DOUBLE
                || t == Schema.DisplayType.CURRENCY
                || t == Schema.DisplayType.PERCENT) {
                if (value instanceof Decimal || value instanceof Integer
                    || value instanceof Long || value instanceof Double) {
                    return Decimal.valueOf(Double.valueOf(String.valueOf(value)));
                }
                return Decimal.valueOf(Double.valueOf(String.valueOf(value).trim()));
            }
            if (t == Schema.DisplayType.ID || t == Schema.DisplayType.REFERENCE) {
                if (value instanceof Id) {
                    return value;
                }
                return Id.valueOf(String.valueOf(value).trim());
            }
            if (t == Schema.DisplayType.TIME) {
                if (value instanceof Time) {
                    return value;
                }
                throw new SearchException('Invalid Time value for ' + d.getName());
            }
            // Text-like fields (string, picklist, email, phone, url, textarea...)
            if (value instanceof String) {
                return value;
            }
            return String.valueOf(value);
        } catch (SearchException e) {
            throw e;
        } catch (Exception e) {
            throw new SearchException(
                'Invalid value for field ' + d.getName() + ': ' + e.getMessage()
            );
        }
    }
}
