```apex
public with sharing class ContactLookupAction {

    public class Request {
        @InvocableVariable(label='Email' description='Email address to search for' required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable(label='Contact Id' description='Id of the earliest created matching contact')
        public Id contactId;

        @InvocableVariable(label='Found' description='True if a contact was found')
        public Boolean found;
    }

    @InvocableMethod(label='Find Contact by Email' description='Finds the earliest created contact with the given email, case-insensitively' category='Contact')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();
        if (requests == null || requests.isEmpty()) {
            return results;
        }

        // Normalized (trimmed, lowercased) email per request; null if blank
        List<String> normalized = new List<String>();
        Set<String> emailSet = new Set<String>();
        for (Request req : requests) {
            String key = null;
            if (req != null && req.email != null) {
                String trimmed = req.email.trim();
                if (String.isNotBlank(trimmed)) {
                    key = trimmed.toLowerCase();
                    emailSet.add(key);
                }
            }
            normalized.add(key);
        }

        // Earliest contact per lowercased email
        Map<String, Id> idByEmail = new Map<String, Id>();
        if (!emailSet.isEmpty()) {
            List<String> emails = new List<String>(emailSet);
            for (Contact c : [
                SELECT Id, Email
                FROM Contact
                WHERE Email IN :emails
                WITH USER_MODE
                ORDER BY CreatedDate ASC, Id ASC
            ]) {
                String key = c.Email == null ? null : c.Email.trim().toLowerCase();
                if (key != null && !idByEmail.containsKey(key)) {
                    idByEmail.put(key, c.Id);
                }
            }
        }

        for (String key : normalized) {
            Result r = new Result();
            Id contactId = key == null ? null : idByEmail.get(key);
            r.contactId = contactId;
            r.found = contactId != null;
            results.add(r);
        }
        return results;
    }
}
