public with sharing class OrderPayloadParser {

    public class PayloadException extends Exception {}

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Body is empty');
        }
        try {
            return doParse(body);
        } catch (PayloadException e) {
            throw e;
        } catch (Exception e) {
            throw new PayloadException('Invalid payload: ' + e.getMessage());
        }
    }

    private static Order doParse(String body) {
        Object parsed = JSON.deserializeUntyped(body);
        if (!(parsed instanceof Map<String, Object>)) {
            throw new PayloadException('Payload is not a JSON object');
        }
        Map<String, Object> root = (Map<String, Object>) parsed;

        Order o = new Order();
        Object num = root.get('number');
        if (num == null || String.isBlank(String.valueOf(num))) {
            throw new PayloadException('Missing order number');
        }
        o.orderNumber = String.valueOf(num).trim();

        Object d = root.get('date');
        if (d != null && !(d instanceof String)) {
            throw new PayloadException('Invalid date');
        }
        if (d != null && String.isNotBlank((String) d)) {
            o.orderDate = Date.valueOf(((String) d).trim());
        }

        Object cur = root.get('currency');
        o.currencyCode = cur == null ? null : String.valueOf(cur);

        Object cust = root.get('customer');
        if (cust instanceof Map<String, Object>) {
            Object em = ((Map<String, Object>) cust).get('email');
            o.customerEmail = em == null ? null : String.valueOf(em);
        }

        o.lines = new List<Line>();
        o.total = 0;
        Object rawLines = root.get('lines');
        if (rawLines != null) {
            if (!(rawLines instanceof List<Object>)) {
                throw new PayloadException('lines must be an array');
            }
            for (Object item : (List<Object>) rawLines) {
                if (!(item instanceof Map<String, Object>)) {
                    throw new PayloadException('Line is not an object');
                }
                Line l = parseLine((Map<String, Object>) item);
                o.lines.add(l);
                o.total += l.lineTotal;
            }
        }
        o.total = o.total.setScale(2, RoundingMode.HALF_UP);
        return o;
    }

    private static Line parseLine(Map<String, Object> m) {
        Line l = new Line();
        Object sku = m.get('sku');
        if (sku == null || String.isBlank(String.valueOf(sku))) {
            throw new PayloadException('Line missing sku');
        }
        l.sku = String.valueOf(sku);

        Object q = m.get('quantity');
        if (q == null || !(q instanceof Integer || q instanceof Long || q instanceof Decimal)) {
            throw new PayloadException('Line has invalid quantity');
        }
        Decimal qd = toDecimal(q);
        if (qd <= 0 || qd != qd.setScale(0)) {
            throw new PayloadException('Line quantity must be a positive integer');
        }
        l.quantity = qd.intValue();

        Object p = m.get('unitPrice');
        if (p == null || !(p instanceof Integer || p instanceof Long || p instanceof Decimal)) {
            throw new PayloadException('Line has invalid unitPrice');
        }
        l.unitPrice = toDecimal(p);
        if (l.unitPrice < 0) {
            throw new PayloadException('Line unitPrice is negative');
        }

        Object disc = m.get('discount');
        if (disc == null) {
            l.discount = 0;
        } else if (disc instanceof Integer || disc instanceof Long || disc instanceof Decimal) {
            l.discount = toDecimal(disc);
        } else {
            throw new PayloadException('Line has invalid discount');
        }
        if (l.discount < 0 || l.discount > 1) {
            throw new PayloadException('Line discount out of range');
        }

        l.lineTotal = (l.quantity * l.unitPrice * (1 - l.discount))
            .setScale(2, RoundingMode.HALF_UP);
        return l;
    }

    private static Decimal toDecimal(Object o) {
        if (o instanceof Decimal) {
            return (Decimal) o;
        }
        return Decimal.valueOf((Long) (o instanceof Integer ? (Long) ((Integer) o) : o));
    }

    public static String toAcknowledgement(Order order) {
        JSONGenerator g = JSON.createGenerator(false);
        g.writeStartObject();
        g.writeStringField('number', order.orderNumber);
        g.writeStringField('status', 'RECEIVED');
        g.writeNumberField('lineCount', order.lines == null ? 0 : order.lines.size());
        g.writeNumberField('total', order.total == null ? 0 : order.total);
        g.writeEndObject();
        return g.getAsString();
    }
}
