The test class below uses one configurable mock that records the request, so each test can assert the full request contract (method, endpoint, `Content-Type` header, body). I have not compiled or run it.

The mock also counts callouts, so the blank-street tests can check that no callout happens. Blank is covered for null, empty and whitespace-only streets.

Response cases covered: `VERIFIED`, `INVALID`, `CORRECTED` and non-200 statuses. A `CORRECTED` response must overwrite all four fields and set `changed`. `VERIFIED` and `INVALID` must leave the account untouched and `changed` false. A 500 and a 400 both throw, and the message must contain the status code. A 201 and a 204 are also tested, since a check like `>= 300` or `== 500` would let them through.

The request body is parsed and compared field by field, so a swapped or missing field fails a test. I use distinct values for each field to catch swaps.

```apex
@IsTest
private class AddressVerificationServiceTest {

    private class Mock implements HttpCalloutMock {
        Integer statusCode;
        String responseBody;
        Integer calls = 0;
        HttpRequest captured;

        Mock(Integer statusCode, String responseBody) {
            this.statusCode = statusCode;
            this.responseBody = responseBody;
        }

        public HttpResponse respond(HttpRequest req) {
            calls++;
            captured = req;
            HttpResponse res = new HttpResponse();
            res.setStatusCode(statusCode);
            res.setHeader('Content-Type', 'application/json');
            res.setBody(responseBody);
            return res;
        }
    }

    private static Account acct() {
        return new Account(
            Name = 'Test',
            BillingStreet = '1 Main St',
            BillingCity = 'Springfield',
            BillingPostalCode = '12345',
            BillingCountry = 'US'
        );
    }

    private static String statusBody(String status) {
        return '{"status":"' + status + '","address":{"street":"9 Other Rd","city":"Shelbyville","postalCode":"99999","country":"CA"}}';
    }

    private static void assertUntouched(Account a) {
        System.assertEquals('1 Main St', a.BillingStreet);
        System.assertEquals('Springfield', a.BillingCity);
        System.assertEquals('12345', a.BillingPostalCode);
        System.assertEquals('US', a.BillingCountry);
    }

    @IsTest
    static void blankStreetIsSkipped() {
        Mock m = new Mock(200, statusBody('VERIFIED'));
        Test.setMock(HttpCalloutMock.class, m);
        List<String> streets = new List<String>{ null, '', '   ' };
        Test.startTest();
        for (String s : streets) {
            Account a = acct();
            a.BillingStreet = s;
            AddressVerificationService.Result r = AddressVerificationService.verify(a);
            System.assertEquals('SKIPPED', r.status);
            System.assertEquals(false, r.changed);
            System.assertEquals(s, a.BillingStreet);
        }
        Test.stopTest();
        System.assertEquals(0, m.calls);
    }

    @IsTest
    static void requestMatchesContract() {
        Mock m = new Mock(200, statusBody('VERIFIED'));
        Test.setMock(HttpCalloutMock.class, m);
        Test.startTest();
        AddressVerificationService.verify(acct());
        Test.stopTest();
        System.assertEquals(1, m.calls);
        System.assertEquals('POST', m.captured.getMethod());
        System.assertEquals('callout:FB_Address_API/v2/verify', m.captured.getEndpoint());
        System.assertEquals('application/json', m.captured.getHeader('Content-Type'));
        Map<String, Object> body = (Map<String, Object>) JSON.deserializeUntyped(m.captured.getBody());
        System.assertEquals(4, body.size());
        System.assertEquals('1 Main St', body.get('street'));
        System.assertEquals('Springfield', body.get('city'));
        System.assertEquals('12345', body.get('postalCode'));
        System.assertEquals('US', body.get('country'));
    }

    @IsTest
    static void verifiedLeavesAccountUntouched() {
        Test.setMock(HttpCalloutMock.class, new Mock(200, statusBody('VERIFIED')));
        Account a = acct();
        Test.startTest();
        AddressVerificationService.Result r = AddressVerificationService.verify(a);
        Test.stopTest();
        System.assertEquals('VERIFIED', r.status);
        System.assertEquals(false, r.changed);
        assertUntouched(a);
    }

    @IsTest
    static void invalidLeavesAccountUntouched() {
        Test.setMock(HttpCalloutMock.class, new Mock(200, statusBody('INVALID')));
        Account a = acct();
        Test.startTest();
        AddressVerificationService.Result r = AddressVerificationService.verify(a);
        Test.stopTest();
        System.assertEquals('INVALID', r.status);
        System.assertEquals(false, r.changed);
        assertUntouched(a);
    }

    @IsTest
    static void correctedOverwritesAddress() {
        Test.setMock(HttpCalloutMock.class, new Mock(200, statusBody('CORRECTED')));
        Account a = acct();
        Test.startTest();
        AddressVerificationService.Result r = AddressVerificationService.verify(a);
        Test.stopTest();
        System.assertEquals('CORRECTED', r.status);
        System.assertEquals(true, r.changed);
        System.assertEquals('9 Other Rd', a.BillingStreet);
        System.assertEquals('Shelbyville', a.BillingCity);
        System.assertEquals('99999', a.BillingPostalCode);
        System.assertEquals('CA', a.BillingCountry);
    }

    @IsTest
    static void nonOkStatusesThrow() {
        List<Integer> codes = new List<Integer>{ 500, 400, 404, 201, 204, 302 };
        for (Integer code : codes) {
            Test.setMock(HttpCalloutMock.class, new Mock(code, statusBody('CORRECTED')));
            Account a = acct();
            Boolean thrown = false;
            Test.startTest();
            try {
                AddressVerificationService.verify(a);
            } catch (AddressVerificationService.AddressVerificationException e) {
                thrown = true;
                System.assert(e.getMessage().contains(String.valueOf(code)), e.getMessage());
            }
            Test.stopTest();
            System.assert(thrown, 'Expected exception for ' + code);
            assertUntouched(a);
        }
    }
}
