public with sharing class AccountScoringJob implements Queueable {
    private static final Integer CHUNK_SIZE = 200;

    private final List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds == null ? new List<Id>() : new List<Id>(accountIds);
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }

    public void execute(QueueableContext context) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Integer chunkEnd = Math.min(CHUNK_SIZE, accountIds.size());
        Set<Id> batch = new Set<Id>();
        for (Integer i = 0; i < chunkEnd; i++) {
            batch.add(accountIds[i]);
        }

        List<Id> remaining = new List<Id>();
        for (Integer i = chunkEnd; i < accountIds.size(); i++) {
            remaining.add(accountIds[i]);
        }

        List<Account> toUpdate = new List<Account>();
        for (Account a : [
            SELECT Id, AnnualRevenue, Rating
            FROM Account
            WHERE Id IN :batch
            WITH USER_MODE
        ]) {
            String newRating = rate(a.AnnualRevenue);
            if (a.Rating != newRating) {
                a.Rating = newRating;
                toUpdate.add(a);
            }
        }

        if (!toUpdate.isEmpty()) {
            update as user toUpdate;
        }

        if (!remaining.isEmpty()) {
            System.enqueueJob(new AccountScoringJob(remaining));
        }
    }

    @TestVisible
    private static String rate(Decimal annualRevenue) {
        if (annualRevenue != null && annualRevenue >= 1000000) {
            return 'Hot';
        }
        if (annualRevenue != null && annualRevenue >= 100000) {
            return 'Warm';
        }
        return 'Cold';
    }
}
