public with sharing class OpportunityRollupService {

    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> result = new Map<Id, Decimal>();
        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        // Pre-populate every requested, non-null Id with zero
        Set<Id> requested = new Set<Id>();
        for (Id accId : accountIds) {
            if (accId != null) {
                requested.add(accId);
                result.put(accId, 0);
            }
        }
        if (requested.isEmpty()) {
            return result;
        }

        for (AggregateResult ar : [
            SELECT AccountId acc, SUM(Amount) total
            FROM Opportunity
            WHERE AccountId IN :requested
              AND IsWon = true
              AND CloseDate = THIS_YEAR
            GROUP BY AccountId
            WITH USER_MODE
        ]) {
            Id accId = (Id) ar.get('acc');
            Decimal total = (Decimal) ar.get('total');
            if (accId != null && result.containsKey(accId)) {
                result.put(accId, total == null ? 0 : total);
            }
        }
        return result;
    }
