    public static Integer closeStale(Date cutoff) {
        Integer closedCount = 0;

        for (List<Opportunity> chunk : [
            SELECT Id, StageName
            FROM Opportunity
            WHERE IsClosed = false
            AND CloseDate < :cutoff
        ]) {
            for (Opportunity opp : chunk) {
                opp.StageName = 'Closed Lost';
            }

            // allOrNone=false so one bad record (validation rule, etc.) doesn't abort the whole run
            List<Database.SaveResult> results = Database.update(chunk, false);
            for (Database.SaveResult sr : results) {
                if (sr.isSuccess()) {
                    closedCount++;
                } else {
                    System.debug(LoggingLevel.ERROR,
                        'StaleOpportunityCloser failed: ' + sr.getErrors()[0].getMessage());
                }
            }
        }

        return closedCount;
    }
}
