public with sharing class ErpCustomerSync implements Queueable, Database.AllowsCallouts {

    private static final Integer MAX_BATCH = 200;

    private final List<Id> accountIds;

    public ErpCustomerSync(List<Id> accountIds) {
        this.accountIds = accountIds;
    }

    // Called from the trigger: only one Queueable job is enqueued per transaction.
    public static void enqueue(Set<Id> ids) {
        if (ids == null || ids.isEmpty()) {
            return;
        }
        System.enqueueJob(new ErpCustomerSync(new List<Id>(ids)));
    }

    public void execute(QueueableContext context) {
        // Re-query so we send current, committed data
        List<Account> accounts = [
            SELECT Id, Name, BillingCountry
            FROM Account
            WHERE Id IN :accountIds
            ORDER BY CreatedDate, Id
            LIMIT :MAX_BATCH
        ];
        if (accounts.isEmpty()) {
            return;
        }

        List<Map<String, Object>> payload = new List<Map<String, Object>>();
        for (Account a : accounts) {
            String country = String.isBlank(a.BillingCountry) ? null : a.BillingCountry;
            payload.add(new Map<String, Object>{
                'salesforceId' => String.valueOf(a.Id),
                'name' => a.Name,
                'country' => country
            });
        }

        HttpRequest req = new HttpRequest();
        req.setEndpoint('callout:ERP/api/customers');
        req.setMethod('POST');
        req.setHeader('Content-Type', 'application/json');
        req.setBody(JSON.serialize(payload));

        // Expected response: 202 Accepted. Error handling/retries are out of scope.
        new Http().send(req);
    }
}
