public with sharing class LineItemDiscountHandler {

    public static void applyStandardDiscounts(List<OpportunityLineItem> lines) {
        List<OpportunityLineItem> targets = new List<OpportunityLineItem>();
        Set<Id> pbeIds = new Set<Id>();

        for (OpportunityLineItem line : lines) {
            if (line.Discount == null) {
                targets.add(line);
                if (line.Product2Id == null && line.PricebookEntryId != null) {
                    pbeIds.add(line.PricebookEntryId);
                }
            }
        }
        if (targets.isEmpty()) {
            return;
        }

        // Resolve product from price book entry when Product2Id is not populated yet
        Map<Id, Id> productByPbe = new Map<Id, Id>();
        if (!pbeIds.isEmpty()) {
            for (PricebookEntry pbe : [
                SELECT Id, Product2Id FROM PricebookEntry WHERE Id IN :pbeIds
            ]) {
                productByPbe.put(pbe.Id, pbe.Product2Id);
            }
        }

        Set<Id> productIds = new Set<Id>();
        for (OpportunityLineItem line : targets) {
            Id productId = resolveProductId(line, productByPbe);
            if (productId != null) {
                productIds.add(productId);
            }
        }
        if (productIds.isEmpty()) {
            return;
        }

        // One query for all products instead of one per line
        Map<Id, Product2> products = new Map<Id, Product2>([
            SELECT Id, Family FROM Product2 WHERE Id IN :productIds
        ]);

        for (OpportunityLineItem line : targets) {
            Id productId = resolveProductId(line, productByPbe);
            Product2 product = productId == null ? null : products.get(productId);
            if (product != null) {
                // Rules stay in PricingRules; no per-line SOQL
                line.Discount = PricingRules.standardDiscountForFamily(product.Family);
            }
        }
    }

    private static Id resolveProductId(OpportunityLineItem line, Map<Id, Id> productByPbe) {
        if (line.Product2Id != null) {
            return line.Product2Id;
        }
        return line.PricebookEntryId == null ? null : productByPbe.get(line.PricebookEntryId);
    }
}
