public with sharing class RenewalReminderService {

    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opps = [
            SELECT Id, Name, CloseDate, OwnerId, Owner.IsActive
            FROM Opportunity
            WHERE Id IN :opportunityIds
            WITH USER_MODE
        ];

        List<Messaging.SingleEmailMessage> messages = new List<Messaging.SingleEmailMessage>();
        for (Opportunity opp : opps) {
            if (opp.Owner == null || opp.Owner.IsActive != true) {
                continue;
            }
            Messaging.SingleEmailMessage mail = new Messaging.SingleEmailMessage();
            mail.setTargetObjectId(opp.OwnerId);
            mail.setSaveAsActivity(false);
            mail.setSubject('Renewal due: ' + opp.Name);
            String closeDate = opp.CloseDate == null ? 'not set' : opp.CloseDate.format();
            mail.setPlainTextBody(
                'The opportunity "' + opp.Name + '" is due for renewal. ' +
                'Its close date is ' + closeDate + '.'
            );
            messages.add(mail);
        }

        if (messages.isEmpty()) {
            return 0;
        }

        // One sendEmail call for the whole batch (limit: 10 invocations per transaction).
        // allOrNone=false so a failure on one message does not stop the others.
        Integer sent = 0;
        List<Messaging.SendEmailResult> results = Messaging.sendEmail(messages, false);
        for (Messaging.SendEmailResult result : results) {
            if (result.isSuccess()) {
                sent++;
            } else {
                for (Messaging.SendEmailError err : result.getErrors()) {
                    System.debug(LoggingLevel.ERROR,
                        'Renewal reminder failed: ' + err.getStatusCode() + ' - ' + err.getMessage());
                }
            }
        }
        return sent;
    }
}
