public with sharing class AccountCountrySync {

    public static void syncContactCountries(List<Account> newAccounts, Map<Id, Account> oldMap) {
        Map<Id, Account> changed = new Map<Id, Account>();
        Set<String> oldCountries = new Set<String>();

        for (Account acc : newAccounts) {
            Account oldAcc = oldMap == null ? null : oldMap.get(acc.Id);
            if (oldAcc != null && acc.BillingCountry != oldAcc.BillingCountry) {
                changed.put(acc.Id, acc);
                if (String.isNotBlank(oldAcc.BillingCountry)) {
                    oldCountries.add(oldAcc.BillingCountry);
                }
            }
        }
        if (changed.isEmpty()) {
            return;
        }

        List<Contact> toUpdate = new List<Contact>();
        Set<Id> changedIds = changed.keySet();

        // Single selective query, restricted to affected accounts and candidate contacts
        for (Contact c : [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :changedIds
              AND (MailingCountry = null OR MailingCountry IN :oldCountries)
        ]) {
            Account newAcc = changed.get(c.AccountId);
            Account oldAcc = oldMap.get(c.AccountId);
            if (newAcc == null || oldAcc == null) {
                continue;
            }
            Boolean followsAccount = String.isBlank(c.MailingCountry)
                || c.MailingCountry == oldAcc.BillingCountry;
            if (followsAccount) {
                toUpdate.add(new Contact(Id = c.Id, MailingCountry = newAcc.BillingCountry));
            }
        }

        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
