import { LightningElement, api, wire } from 'lwc';
import { getRecord, getFieldValue } from 'lightning/uiRecordApi';
import NAME_FIELD from '@salesforce/schema/Account.Name';
import INDUSTRY_FIELD from '@salesforce/schema/Account.Industry';
import REVENUE_FIELD from '@salesforce/schema/Account.AnnualRevenue';
import OWNER_NAME_FIELD from '@salesforce/schema/Account.Owner.Name';

const FIELDS = [NAME_FIELD, INDUSTRY_FIELD, REVENUE_FIELD, OWNER_NAME_FIELD];

export default class AccountHeader extends LightningElement {
    // Reactive: the wire re-provisions whenever recordId changes
    @api recordId;

    record;
    error;

    @wire(getRecord, { recordId: '$recordId', fields: FIELDS })
    wiredRecord({ data, error }) {
        if (data) {
            this.record = data;
            this.error = undefined;
        } else if (error) {
            this.error = error;
            this.record = undefined;
        } else {
            this.record = undefined;
            this.error = undefined;
        }
    }

    get isLoading() {
        return !this.record && !this.error;
    }

    get hasData() {
        return !!this.record;
    }

    get name() {
        return getFieldValue(this.record, NAME_FIELD);
    }

    get industry() {
        return getFieldValue(this.record, INDUSTRY_FIELD);
    }

    get revenue() {
        return getFieldValue(this.record, REVENUE_FIELD);
    }

    get ownerName() {
        return getFieldValue(this.record, OWNER_NAME_FIELD);
    }

    get errorMessage() {
        return this.error && this.error.body
            ? this.error.body.message
            : this.error && this.error.message;
    }
}
