        try {
            await deleteRecord(row.Id);
            this._rows = this._rows.filter((r) => r.Id !== row.Id);
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Opportunity deleted',
                    message: `"${row.Name}" was deleted.`,
                    variant: 'success'
