        this.editors.forEach((editor) => editor.reset());
    }

    handleSubmit() {
        const editors = this.editors;
        // Validate every editor (no short-circuit) so all errors show at once.
        const results = editors.map((editor) => editor.validate());
        const allValid = results.every((valid) => valid === true);

        if (allValid) {
            this.showError = false;
            this.dispatchEvent(
                new CustomEvent('submit', {
                    detail: { lines: editors.map((editor) => editor.getValue()) }
                })
            );
        } else {
            this.showError = true;
        }
    }
}
