```javascript
import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const REFRESH_MS = 60000;

export default class QueueMonitor extends LightningElement {
    stats;
    errorMessage;

    _intervalId;
    _isLoading = false;
    _session = 0;
    _visibilityHandler;

    get hasStats() {
        return !!this.stats;
    }

    get waiting() {
        return this.stats ? this.stats.waiting : '';
    }

    get longestWaitMinutes() {
        return this.stats ? this.stats.longestWaitMinutes : '';
    }

    connectedCallback() {
        this._session += 1;
        this._isLoading = false;
        this._visibilityHandler = () => this.handleVisibilityChange();
        document.addEventListener('visibilitychange', this._visibilityHandler);
        if (document.visibilityState !== 'hidden') {
            this.startPolling();
        }
    }

    disconnectedCallback() {
        this._session += 1; // invalidate any in-flight response
        this._isLoading = false;
        this.stopPolling();
        if (this._visibilityHandler) {
            document.removeEventListener(
                'visibilitychange',
                this._visibilityHandler
            );
            this._visibilityHandler = undefined;
        }
    }

    handleVisibilityChange() {
        if (document.visibilityState === 'hidden') {
            this.stopPolling();
        } else {
            this.startPolling();
        }
    }

    startPolling() {
        this.stopPolling();
        this.loadStats();
        this._intervalId = setInterval(() => {
            if (document.visibilityState === 'hidden') {
                return;
            }
            this.loadStats();
        }, REFRESH_MS);
    }

    stopPolling() {
        if (this._intervalId !== undefined) {
            clearInterval(this._intervalId);
            this._intervalId = undefined;
        }
    }

    loadStats() {
        if (this._isLoading || document.visibilityState === 'hidden') {
            return;
        }
        this._isLoading = true;
        const session = this._session;
        getQueueStats()
            .then((result) => {
                if (session !== this._session) {
                    return;
                }
                this.stats = result;
                this.errorMessage = undefined;
            })
            .catch((error) => {
                if (session !== this._session) {
                    return;
                }
                this.errorMessage =
                    (error && error.body && error.body.message) ||
                    (error && error.message) ||
                    'Unknown error';
            })
            .finally(() => {
                if (session === this._session) {
                    this._isLoading = false;
                }
            });
    }
}
