import { LightningElement } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import register from '@salesforce/apex/RegistrationController.register';

const PERSONAL_DOMAINS = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';
    isSaving = false;

    handleChange(event) {
        const field = event.target.dataset.field;
        if (field) {
            this[field] = event.detail.value;
        }
    }

    isPersonalEmail(value) {
        if (!value) {
            return false;
        }
        const at = value.lastIndexOf('@');
        if (at < 0) {
            return false;
        }
        const domain = value.substring(at + 1).trim().toLowerCase();
        return PERSONAL_DOMAINS.includes(domain);
    }

    async handleRegister() {
        if (this.isSaving) {
            return;
        }
        const inputs = Array.from(this.template.querySelectorAll('lightning-input'));

        const emailInput = inputs.find((i) => i.dataset.field === 'email');
        if (emailInput) {
            emailInput.setCustomValidity(
                this.isPersonalEmail(this.email) ? 'Use your work email address.' : ''
            );
        }

        // report on every input (no short-circuit)
        const results = inputs.map((i) => i.reportValidity());
        if (results.includes(false)) {
            return;
        }

        this.isSaving = true;
        try {
            await register({
                fullName: this.fullName,
                email: this.email,
                company: this.company
            });
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registered',
                    message: 'You are registered for the event.',
                    variant: 'success'
                })
            );
        } catch (error) {
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registration failed',
                    message: error && error.body ? error.body.message : undefined,
                    variant: 'error'
                })
            );
        } finally {
            this.isSaving = false;
        }
    }
}
