```javascript
import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label;

    _options = [];
    _value;
    _activeIndex = -1; // -1 means "derive from selection / first"
    _activeValue;
    _hasActive = false;

    @api
    get options() {
        return this._options;
    }
    set options(v) {
        this._options = Array.isArray(v) ? v : [];
    }

    @api
    get value() {
        return this._value;
    }
    set value(v) {
        this._value = v;
        // parent change moves the active option to the selection
        this._hasActive = false;
    }

    get _selectedIndex() {
        return this._options.findIndex((o) => o.value === this._value);
    }

    get activeIdx() {
        const n = this._options.length;
        if (!n) return -1;
        if (this._hasActive) {
            const i = this._options.findIndex(
                (o) => o.value === this._activeValue
            );
            if (i >= 0) return i;
        }
        const s = this._selectedIndex;
        return s >= 0 ? s : 0;
    }

    get activeDescendantId() {
        const i = this.activeIdx;
        return i >= 0 ? 'opt-' + i : undefined;
    }

    get items() {
        return this._options.map((o, index) => {
            const selected = o.value === this._value;
            return {
                key: 'k-' + index,
                id: 'opt-' + index,
                index,
                value: o.value,
                label: o.label,
                ariaSelected: selected ? 'true' : 'false'
            };
        });
    }

    setActive(i) {
        const n = this._options.length;
        if (!n) return;
        const idx = Math.max(0, Math.min(n - 1, i));
        this._activeValue = this._options[idx].value;
        this._hasActive = true;
    }

    select(i) {
        const opt = this._options[i];
        if (!opt) return;
        this.setActive(i);
        if (opt.value === this._value) return;
        this._value = opt.value;
        this.dispatchEvent(
            new CustomEvent('change', { detail: { value: opt.value } })
        );
    }

    handleKeydown(event) {
        const n = this._options.length;
        switch (event.key) {
            case 'ArrowDown':
                event.preventDefault();
                this.setActive(this.activeIdx + 1);
                break;
            case 'ArrowUp':
                event.preventDefault();
                this.setActive(this.activeIdx - 1);
                break;
            case 'Home':
                event.preventDefault();
                this.setActive(0);
                break;
            case 'End':
                event.preventDefault();
                this.setActive(n - 1);
                break;
            case 'Enter':
            case ' ':
                event.preventDefault();
                if (n) this.select(this.activeIdx);
                break;
            default:
                break;
        }
    }

    handleClick(event) {
        const i = Number(event.currentTarget.dataset.index);
        this.select(i);
    }
}
