public with sharing class HouseholdService {

    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must not be null or empty');
        }
        for (Contact c : members) {
            if (c == null) {
                throw new IllegalArgumentException('members must not contain null');
            }
        }

        Schema.RecordTypeInfo rti = Schema.SObjectType.Account
            .getRecordTypeInfosByDeveloperName().get('HH_Account');
        if (rti == null) {
            throw new IllegalArgumentException('Household Account record type (HH_Account) not found');
        }

        Savepoint sp = Database.setSavepoint();
        try {
            // Name is a required platform field; NPSP household naming
            // replaces it with the generated household name.
            Account hh = new Account(
                Name = 'Household',
                RecordTypeId = rti.getRecordTypeId()
            );
            insert hh;

            for (Contact c : members) {
                c.AccountId = hh.Id;
            }
            insert members;

            update new Account(
                Id = hh.Id,
                npe01__One2OneContact__c = members[0].Id
            );

            return hh.Id;
        } catch (Exception e) {
            Database.rollback(sp);
            throw e;
        }
    }
}
