```apex
public with sharing class FamilyService {

    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        Set<Id> childIds = new Set<Id>();
        Set<Id> parentIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }
            childIds.add(childId);
            parentIds.add(parentId);
        }
        if (childIds.isEmpty()) {
            return;
        }

        Set<Id> allIds = new Set<Id>(childIds);
        allIds.addAll(parentIds);

        // Single query: any existing relationship between the involved contacts, either direction
        Set<String> existing = new Set<String>();
        for (npe4__Relationship__c r : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :allIds
            AND npe4__RelatedContact__c IN :allIds
        ]) {
            existing.add(key(r.npe4__Contact__c, r.npe4__RelatedContact__c));
            existing.add(key(r.npe4__RelatedContact__c, r.npe4__Contact__c));
        }

        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }
            String k = key(childId, parentId);
            if (existing.contains(k)) {
                continue;
            }
            existing.add(k);
            existing.add(key(parentId, childId));

            // Parent is the child's Parent. NPSP's trigger creates the reciprocal
            // (Son/Daughter/Child) on the parent record from the Relationship Lookup.
            toInsert.add(new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = 'Parent',
                npe4__Status__c = 'Current'
            ));
        }

        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }

    private static String key(Id a, Id b) {
        return String.valueOf(a) + '|' + String.valueOf(b);
    }
}
