```apex
public inherited sharing class TA_Case_RollupOpenCount implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate, TriggerAction.AfterDelete, TriggerAction.AfterUndelete {
    public void afterInsert(List<SObject> triggerNew) {
        recalc(collect(triggerNew, null));
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        recalc(collect(triggerNew, triggerOld));
    }

    public void afterDelete(List<SObject> triggerOld) {
        recalc(collect(triggerOld, null));
    }

    public void afterUndelete(List<SObject> triggerNew) {
        recalc(collect(triggerNew, null));
    }

    private static Set<Id> collect(List<SObject> current, List<SObject> old) {
        Set<Id> ids = new Set<Id>();
        for (Integer i = 0; i < current.size(); i++) {
            Case c = (Case) current[i];
            if (old == null) {
                if (c.AccountId != null) {
                    ids.add(c.AccountId);
                }
            } else {
                Case o = (Case) old[i];
                if (c.AccountId != o.AccountId || c.IsClosed != o.IsClosed) {
                    if (c.AccountId != null) {
                        ids.add(c.AccountId);
                    }
                    if (o.AccountId != null) {
                        ids.add(o.AccountId);
                    }
                }
            }
        }
        return ids;
    }

    private static void recalc(Set<Id> accountIds) {
        if (accountIds.isEmpty()) {
            return;
        }
        Map<Id, Account> toUpdate = new Map<Id, Account>();
        for (Id accId : accountIds) {
            toUpdate.put(accId, new Account(Id = accId, FB_Open_Case_Count__c = 0));
        }
        for (AggregateResult ar : [
            SELECT AccountId acc, COUNT(Id) cnt
            FROM Case
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accId = (Id) ar.get('acc');
            toUpdate.get(accId).FB_Open_Case_Count__c = Integer.valueOf(ar.get('cnt'));
        }
        Database.update(toUpdate.values(), false);
    }
}
